Object.assign(SNIP,{});PRESET_NOTES["l41"]={"Ví dụ: Chọn nhiều hoạt động nhất": "Nhận [1,4), bỏ các khoảng bắt đầu trước 4, nhận [5,7), rồi [8,11): 3 hoạt động. Không có cách nào nhận được 4.", "Ví dụ: Sắp theo bắt đầu sớm nhất là sai": "Theo bắt đầu sớm nhất, [0,10) được nhận đầu tiên và chặn mọi khoảng khác: 1 hoạt động. Theo kết thúc sớm nhất: [1,2), [3,4), [5,6): 3 hoạt động.", "Ví dụ: Số phòng tối thiểu": "Không cần biết mốc bắt đầu nào đi với mốc kết thúc nào: chỉ cần đếm. Tại thời điểm 5 có [1,5) vừa xong, [4,7) và [5,6) đang diễn ra; lúc 2 có [1,5), [2,4): nhiều nhất 2 hoạt động cùng lúc, cần 2 phòng.", "Ví dụ: Hạn chót sớm nhất trước": "Các việc xong lúc 2, 3, 6, 8; trễ 0, 0, 1, 2. Độ trễ lớn nhất là 2, không có thứ tự nào tốt hơn.", "Lỗi: so sánh sai ở đầu mút": "In 2 thay vì 3: [3,5) bị loại vì 3 > 3 sai. Đọc kỹ đề: khoảng đóng [s, e] thì hai khoảng chạm nhau là giao (dùng >), khoảng nửa mở [s, e) thì không (dùng >=)."};EX_HINTS["l41"]=[["Sắp theo thời điểm kết thúc tăng dần. Mẹo: lưu cặp {e, s} để sort mặc định sắp theo e.", "Nhận đơn khi s ≥ thời điểm kết thúc của đơn vừa nhận (khoảng nửa mở nên chạm nhau vẫn được).", "Đừng sắp theo thời điểm bắt đầu hay theo độ dài: đều có phản ví dụ trong các test."], ["Số phòng cần = số hoạt động diễn ra cùng lúc nhiều nhất.", "Sắp riêng hai mảng s và e. Khi xét mốc bắt đầu s[i] (đã có i + 1 hoạt động bắt đầu), dời j qua mọi e[j] ≤ s[i] (j hoạt động đã xong). Đang diễn ra: i + 1 − j.", "Dùng e[j] ≤ s[i]: hoạt động xong đúng lúc hoạt động khác bắt đầu thì trả phòng kịp."], ["Làm theo hạn chót tăng dần. Độ dài việc không ảnh hưởng tới thứ tự.", "Cộng dồn thời điểm xong f; độ trễ của việc là f − d nếu dương. Khởi tạo treMax = 0 lo luôn phần max(0, …).", "f có thể tới 10^5 · 10^9: dùng long long."]];
/* ===================== BÀI 41 · Bài toán chọn hoạt động và xếp lịch ===================== */
/* Bài 41 · Bài toán chọn hoạt động và xếp lịch
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR41=[{label:"Ví dụ: Chọn nhiều hoạt động nhất",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    // đã sắp theo thời điểm kết thúc e tăng dần\n    int s[8] = {1, 3, 0, 5, 3, 5, 6, 8};\n    int e[8] = {4, 5, 6, 7, 9, 9, 10, 11};\n    int dem = 0, ketThuc = -1;\n    for (int i = 0; i < 8; i++) {\n        if (s[i] >= ketThuc) {         // không giao với hoạt động vừa nhận\n            dem++;\n            ketThuc = e[i];\n            cout << \"[\" << s[i] << \",\" << e[i] << \") \";\n        }\n    }\n    cout << \"\\n\" << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"e",ptr:["i"]},{type:"cells",of:"s",ptr:["i"]},{type:"vars",names:["dem","ketThuc"]}],py:{code:"# đã sắp theo thời điểm kết thúc e tăng dần\ns = [1, 3, 0, 5, 3, 5, 6, 8]\ne = [4, 5, 6, 7, 9, 9, 10, 11]\ndem, ket_thuc = 0, -1\nchon = []\nfor i in range(len(s)):\n    if s[i] >= ket_thuc:               # không giao với hoạt động vừa nhận\n        dem += 1\n        ket_thuc = e[i]\n        chon.append((s[i], e[i]))\nprint(*chon)\nprint(dem)",viz:[{type:"cells",of:"e",ptr:["i"]},{type:"cells",of:"s",ptr:["i"]},{type:"vars",names:["dem","ket_thuc"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        // đã sắp theo thời điểm kết thúc e tăng dần\n        int[] s = { 1, 3, 0, 5, 3, 5, 6, 8 };\n        int[] e = { 4, 5, 6, 7, 9, 9, 10, 11 };\n        int dem = 0, ketThuc = -1;\n        for (int i = 0; i < s.Length; i++)\n        {\n            if (s[i] >= ketThuc)               // không giao với hoạt động vừa nhận\n            {\n                dem++;\n                ketThuc = e[i];\n                Console.Write(\"[\" + s[i] + \",\" + e[i] + \") \");\n            }\n        }\n        Console.WriteLine();\n        Console.WriteLine(dem);\n    }\n}"}},{label:"Ví dụ: Sắp theo bắt đầu sớm nhất là sai",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int s[4] = {0, 1, 3, 5};\n    int e[4] = {10, 2, 4, 6};\n    // cách 1: duyệt theo s tăng dần (đã đúng thứ tự trên)\n    int dem1 = 0, kt1 = -1;\n    for (int i = 0; i < 4; i++)\n        if (s[i] >= kt1) { dem1++; kt1 = e[i]; }\n    // cách 2: duyệt theo e tăng dần: thứ tự 1, 2, 3, 0\n    int thuTu[4] = {1, 2, 3, 0};\n    int dem2 = 0, kt2 = -1;\n    for (int k = 0; k < 4; k++) {\n        int i = thuTu[k];\n        if (s[i] >= kt2) { dem2++; kt2 = e[i]; }\n    }\n    cout << \"bat dau som: \" << dem1 << \", ket thuc som: \" << dem2 << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["dem1","kt1","dem2","kt2"]}],py:{code:"hd = [(0, 10), (1, 2), (3, 4), (5, 6)]   # (s, e)\n\ndef dem_tham_lam(ds):\n    dem, kt = 0, -1\n    for s, e in ds:\n        if s >= kt:\n            dem += 1\n            kt = e\n    return dem\n\ndem1 = dem_tham_lam(sorted(hd))                          # theo s tăng dần\ndem2 = dem_tham_lam(sorted(hd, key=lambda x: x[1]))      # theo e tăng dần\nprint(\"bat dau som:\", dem1, \", ket thuc som:\", dem2)",viz:[{type:"vars",names:["dem","kt","dem1","dem2"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static int Dem(int[] thuTu, int[] s, int[] e)\n    {\n        int dem = 0, kt = -1;\n        foreach (int i in thuTu)\n            if (s[i] >= kt) { dem++; kt = e[i]; }\n        return dem;\n    }\n\n    static void Main()\n    {\n        int[] s = { 0, 1, 3, 5 };\n        int[] e = { 10, 2, 4, 6 };\n        int[] theoS = { 0, 1, 2, 3 };\n        int[] theoE = { 0, 1, 2, 3 };\n        Array.Sort(theoS, (x, y) => s[x].CompareTo(s[y]));    // chỉ số, sắp theo s\n        Array.Sort(theoE, (x, y) => e[x].CompareTo(e[y]));    // chỉ số, sắp theo e\n        int dem1 = Dem(theoS, s, e), dem2 = Dem(theoE, s, e);\n        Console.WriteLine(\"bat dau som: \" + dem1 + \", ket thuc som: \" + dem2);\n    }\n}",viz:[{type:"vars",names:["dem","kt","dem1","dem2"]}]}},{label:"Ví dụ: Số phòng tối thiểu",input:"",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int s[6] = {1, 2, 4, 6, 5, 8};\n    int e[6] = {5, 4, 7, 9, 6, 10};\n    sort(s, s + 6);                    // các mốc bắt đầu\n    sort(e, e + 6);                    // các mốc kết thúc\n    int j = 0, best = 0;\n    for (int i = 0; i < 6; i++) {\n        while (e[j] <= s[i]) j++;      // trả phòng của các hoạt động đã xong\n        best = max(best, i - j + 1);   // đang dùng: đã bắt đầu i + 1, đã xong j\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]},{type:"cells",of:"e",ptr:["j"]},{type:"vars",names:["best"]}],py:{code:"s = sorted([1, 2, 4, 6, 5, 8])          # các mốc bắt đầu\ne = sorted([5, 4, 7, 9, 6, 10])         # các mốc kết thúc\nj = best = 0\nfor i in range(len(s)):\n    while e[j] <= s[i]:                 # trả phòng của các hoạt động đã xong\n        j += 1\n    best = max(best, i - j + 1)         # đang dùng: đã bắt đầu i + 1, đã xong j\nprint(best)",viz:[{type:"cells",of:"s",ptr:["i"]},{type:"cells",of:"e",ptr:["j"]},{type:"vars",names:["best"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] s = { 1, 2, 4, 6, 5, 8 };\n        int[] e = { 5, 4, 7, 9, 6, 10 };\n        Array.Sort(s);                         // các mốc bắt đầu\n        Array.Sort(e);                         // các mốc kết thúc\n        int j = 0, best = 0;\n        for (int i = 0; i < s.Length; i++)\n        {\n            while (e[j] <= s[i]) j++;          // trả phòng của các hoạt động đã xong\n            best = Math.Max(best, i - j + 1);  // đang dùng: đã bắt đầu i + 1, đã xong j\n        }\n        Console.WriteLine(best);\n    }\n}"}},{label:"Ví dụ: Hạn chót sớm nhất trước",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    // đã sắp theo hạn chót d tăng dần\n    int t[4] = {2, 1, 3, 2};\n    int d[4] = {2, 4, 5, 6};\n    int f = 0, treMax = 0;\n    for (int i = 0; i < 4; i++) {\n        f += t[i];                     // việc i xong lúc f\n        treMax = max(treMax, f - d[i]);\n    }\n    cout << treMax << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"d",ptr:["i"]},{type:"vars",names:["f","treMax"]}],py:{code:"# đã sắp theo hạn chót d tăng dần\nt = [2, 1, 3, 2]\nd = [2, 4, 5, 6]\nf = tre_max = 0\nfor i in range(len(t)):\n    f += t[i]                           # việc i xong lúc f\n    tre_max = max(tre_max, f - d[i])\nprint(tre_max)",viz:[{type:"cells",of:"d",ptr:["i"]},{type:"vars",names:["f","tre_max"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        // đã sắp theo hạn chót d tăng dần\n        int[] t = { 2, 1, 3, 2 };\n        int[] d = { 2, 4, 5, 6 };\n        int f = 0, treMax = 0;\n        for (int i = 0; i < t.Length; i++)\n        {\n            f += t[i];                         // việc i xong lúc f\n            treMax = Math.Max(treMax, f - d[i]);\n        }\n        Console.WriteLine(treMax);\n    }\n}"}},{label:"Lỗi: so sánh sai ở đầu mút",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int s[3] = {1, 3, 5};\n    int e[3] = {3, 5, 7};              // [1,3) [3,5) [5,7): chạm nhau, không giao\n    int dem = 0, ketThuc = -1;\n    for (int i = 0; i < 3; i++) {\n        if (s[i] > ketThuc) {          // SAI với khoảng nửa mở: phải là >=\n            dem++;\n            ketThuc = e[i];\n        }\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]},{type:"vars",names:["dem","ketThuc"]}],py:{code:"s = [1, 3, 5]\ne = [3, 5, 7]                           # [1,3) [3,5) [5,7): chạm nhau, không giao\ndem, ket_thuc = 0, -1\nfor i in range(3):\n    if s[i] > ket_thuc:                 # SAI với khoảng nửa mở: phải là >=\n        dem += 1\n        ket_thuc = e[i]\nprint(dem)",viz:[{type:"cells",of:"s",ptr:["i"]},{type:"vars",names:["dem","ket_thuc"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] s = { 1, 3, 5 };\n        int[] e = { 3, 5, 7 };                 // [1,3) [3,5) [5,7): chạm nhau, không giao\n        int dem = 0, ketThuc = -1;\n        for (int i = 0; i < 3; i++)\n        {\n            if (s[i] > ketThuc)                // SAI với khoảng nửa mở: phải là >=\n            {\n                dem++;\n                ketThuc = e[i];\n            }\n        }\n        Console.WriteLine(dem);\n    }\n}"}}];
