makeEx2(document.getElementById("ex-l41"),sim41,[{t:"Hội trường",d:"Có n đơn đăng ký dùng hội trường, đơn i muốn dùng trong khoảng [sᵢ, eᵢ) (0 ≤ sᵢ < eᵢ ≤ 10^9). Hai đơn nhận được cùng nhau nếu khoảng không giao nhau (chạm đầu mút thì được). Đầu vào: n (1 ≤ n ≤ 10^5), rồi n dòng sᵢ eᵢ. Đầu ra: số đơn nhiều nhất nhận được.",tests:[{in:"8\n1 4\n3 5\n0 6\n5 7\n3 9\n5 9\n6 10\n8 11",out:"3"},{in:"4\n0 10\n1 2\n3 4\n5 6",out:"3"},{in:"3\n1 3\n3 5\n5 7",out:"3"},{in:"3\n0 5\n4 6\n5 10",out:"2"},{in:"1\n2 3",out:"1"},{in:"4\n1 2\n1 2\n1 2\n1 2",out:"1"},{in:"60\n24 30\n14 17\n57 64\n36 48\n18 27\n17 24\n54 66\n48 58\n0 4\n42 43\n28 31\n9 21\n20 23\n16 27\n44 54\n37 38\n7 17\n2 9\n55 60\n53 65\n13 15\n46 52\n46 54\n8 17\n42 43\n7 9\n58 61\n44 47\n3 8\n20 24\n39 40\n38 48\n11 18\n56 57\n19 26\n9 11\n42 44\n26 27\n42 53\n31 38\n14 15\n5 8\n4 12\n60 72\n25 32\n34 46\n17 26\n1 2\n41 49\n20 23\n8 10\n45 46\n46 57\n55 57\n42 54\n8 15\n41 53\n47 49\n38 47\n26 36",out:"14"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<pair<int,int>> v(n);        // lưu {e, s} để sort theo e\n    for (int i = 0; i < n; i++) cin >> v[i].second >> v[i].first;\n    int dem = 0;\n    // sắp theo thời điểm kết thúc, nhận khi s >= thời điểm kết thúc vừa nhận\n    cout << dem << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=0;i<n;i++){const s=(i*7919)%(10*n);r.push(s+" "+(s+1+(i*31)%50))}return n+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Quy hoạch động xét mọi cặp đơn tốn O(n²). Sắp xếp rồi duyệt một lượt là O(n log n)."},py:{start:"n = int(input())\nhd = [tuple(map(int, input().split())) for _ in range(n)]   # (s, e)\ndem = 0\n# sắp theo thời điểm kết thúc, nhận khi s >= thời điểm kết thúc vừa nhận\nprint(dem)",hints:["Sắp theo thời điểm kết thúc: hd.sort(key=lambda x: x[1]).","Nhận đơn khi s ≥ thời điểm kết thúc của đơn vừa nhận (khoảng nửa mở nên chạm nhau vẫn được).","Đừng sắp theo thời điểm bắt đầu hay theo độ dài: đều có phản ví dụ trong các test."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] s = new long[n], e = new long[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            s[i] = t[0];\n            e[i] = t[1];\n        }\n        int dem = 0;\n        // sắp theo thời điểm kết thúc, nhận khi s >= thời điểm kết thúc vừa nhận\n        Console.WriteLine(dem);\n    }\n}",hints:["Sắp theo thời điểm kết thúc. Array.Sort(e, s) sắp mảng khóa e và đổi chỗ s theo cùng thứ tự.","Nhận đơn khi s ≥ thời điểm kết thúc của đơn vừa nhận (khoảng nửa mở nên chạm nhau vẫn được).","Đừng sắp theo thời điểm bắt đầu hay theo độ dài: đều có phản ví dụ trong các test."]}},{t:"Số phòng tối thiểu",d:"Đầu vào giống bài trước: n khoảng [sᵢ, eᵢ). Phải nhận hết các đơn; hai đơn giao nhau phải ở hai phòng khác nhau. Đầu ra: số phòng ít nhất cần dùng.",tests:[{in:"6\n1 5\n2 4\n4 7\n6 9\n5 6\n8 10",out:"2"},{in:"4\n0 10\n1 2\n3 4\n5 6",out:"2"},{in:"3\n1 3\n3 5\n5 7",out:"1"},{in:"4\n1 2\n1 2\n1 2\n1 2",out:"4"},{in:"1\n0 1",out:"1"},{in:"60\n54 56\n60 64\n14 21\n23 35\n29 40\n46 53\n50 58\n5 16\n17 26\n13 24\n15 20\n24 36\n20 30\n24 29\n48 56\n46 48\n13 22\n10 14\n1 5\n11 19\n42 46\n4 8\n35 45\n39 42\n31 37\n7 11\n24 35\n46 48\n52 60\n38 50\n45 49\n35 43\n25 31\n57 62\n52 58\n1 4\n37 49\n60 63\n40 43\n32 41\n41 44\n26 38\n50 52\n2 11\n42 52\n44 50\n13 24\n25 30\n18 21\n16 23\n39 43\n53 55\n55 67\n17 27\n37 44\n19 26\n51 59\n44 48\n6 15\n30 40",out:"10"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> s(n), e(n);\n    for (int i = 0; i < n; i++) cin >> s[i] >> e[i];\n    int best = 0;\n    // sắp riêng s và e; quét các mốc bắt đầu, trả phòng các hoạt động có e <= s[i]\n    cout << best << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=0;i<n;i++){const s=(i*7919)%(10*n);r.push(s+" "+(s+1+(i*31)%50))}return n+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Với mỗi mốc bắt đầu, đếm lại mọi hoạt động chứa nó tốn O(n²)."},py:{start:"n = int(input())\nhd = [tuple(map(int, input().split())) for _ in range(n)]   # (s, e)\nbest = 0\n# sắp riêng các s và các e; quét các mốc bắt đầu, trả phòng các hoạt động có e <= s\nprint(best)",hints:["Số phòng cần = số hoạt động diễn ra cùng lúc nhiều nhất.","Sắp riêng hai danh sách s và e. Khi xét s[i] (đã có i + 1 hoạt động bắt đầu), dời j qua mọi e[j] ≤ s[i] (j hoạt động đã xong). Đang diễn ra: i + 1 − j.","Dùng e[j] ≤ s[i]: hoạt động xong đúng lúc hoạt động khác bắt đầu thì trả phòng kịp."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] s = new long[n], e = new long[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            s[i] = t[0];\n            e[i] = t[1];\n        }\n        int best = 0;\n        // sắp riêng s và e; quét các mốc bắt đầu, trả phòng các hoạt động có e <= s[i]\n        Console.WriteLine(best);\n    }\n}",hints:["Số phòng cần = số hoạt động diễn ra cùng lúc nhiều nhất.","Sắp riêng hai mảng s và e. Khi xét s[i] (đã có i + 1 hoạt động bắt đầu), dời j qua mọi e[j] ≤ s[i] (j hoạt động đã xong). Đang diễn ra: i + 1 − j.","Dùng e[j] ≤ s[i]: hoạt động xong đúng lúc hoạt động khác bắt đầu thì trả phòng kịp."]}},{t:"Trễ hạn ít nhất",d:"Một máy làm lần lượt n việc, bắt đầu từ thời điểm 0, không nghỉ. Việc i tốn tᵢ đơn vị thời gian và có hạn chót dᵢ; xong lúc f thì trễ max(0, f − dᵢ). Đầu vào: n (1 ≤ n ≤ 10^5), rồi n dòng tᵢ dᵢ (1 ≤ tᵢ, dᵢ ≤ 10^9). Đầu ra: độ trễ lớn nhất nhỏ nhất có thể, khi chọn thứ tự làm tốt nhất.",tests:[{in:"4\n3 5\n2 2\n1 4\n2 6",out:"2"},{in:"1\n5 10",out:"0"},{in:"1\n5 1",out:"4"},{in:"2\n1 100\n100 1",out:"99"},{in:"3\n1000000000 1\n1000000000 1\n1000000000 1",out:"2999999999"},{in:"40\n8 30\n8 24\n8 38\n2 32\n8 61\n10 49\n1 79\n9 4\n4 53\n8 42\n6 75\n3 55\n1 29\n3 79\n9 52\n3 4\n10 68\n7 4\n4 35\n10 4\n9 68\n4 50\n3 6\n9 42\n10 66\n3 63\n2 73\n9 6\n4 48\n3 36\n8 12\n8 3\n5 14\n5 50\n2 70\n6 57\n6 66\n3 11\n2 48\n7 45",out:"151"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<pair<long long,long long>> v(n);   // {d, t}\n    for (int i = 0; i < n; i++) cin >> v[i].second >> v[i].first;\n    long long treMax = 0;\n    // làm theo hạn chót sớm nhất trước\n    cout << treMax << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=0;i<n;i++)r.push((1+(i*7)%10)+" "+((i*7919)%(5*n)+1));return n+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Mỗi lần duyệt cả danh sách tìm việc có hạn chót sớm nhất còn lại tốn O(n²). Sắp xếp một lần là O(n log n)."},py:{start:"n = int(input())\nviec = [tuple(map(int, input().split())) for _ in range(n)]   # (t, d)\ntre_max = 0\n# làm theo hạn chót sớm nhất trước\nprint(tre_max)",hints:["Làm theo hạn chót tăng dần: viec.sort(key=lambda x: x[1]). Độ dài việc không ảnh hưởng tới thứ tự.","Cộng dồn thời điểm xong f; độ trễ của việc là f − d nếu dương. Khởi tạo tre_max = 0 lo luôn phần max(0, …).","Tìm việc có hạn chót nhỏ nhất bằng min() mỗi lần là O(n²)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] tg = new long[n], d = new long[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            tg[i] = t[0];\n            d[i] = t[1];\n        }\n        long treMax = 0;\n        // tg[i]: thời gian làm, d[i]: hạn chót; làm theo hạn chót sớm nhất trước\n        Console.WriteLine(treMax);\n    }\n}",hints:["Làm theo hạn chót tăng dần: Array.Sort(d, tg). Độ dài việc không ảnh hưởng tới thứ tự.","Cộng dồn thời điểm xong f; độ trễ của việc là f − d nếu dương. Khởi tạo treMax = 0 lo luôn phần max(0, …).","f có thể tới 10^5 · 10^9: dùng long."]}}]);

makeQuiz("quiz41","score41",[{"q": "Chọn nhiều hoạt động không giao nhau nhất: sắp theo tiêu chí nào?", "o": ["Bắt đầu sớm nhất", "Ngắn nhất", "Kết thúc sớm nhất", "Ít giao nhất"], "a": 2, "e": "Các tiêu chí khác đều có phản ví dụ."}, {"q": "Với khoảng nửa mở [s, e), nhận hoạt động khi?", "o": ["s > ketThuc", "s ≥ ketThuc", "e ≥ ketThuc", "s ≥ e"], "a": 1, "e": "Chạm nhau như [1, 3) và [3, 5) không giao."}, {"q": "Số phòng tối thiểu để nhận hết các hoạt động bằng?", "o": ["Số hoạt động", "Số hoạt động diễn ra cùng lúc nhiều nhất", "n − số hoạt động chọn được", "Hoạt động dài nhất"], "a": 1, "e": "Tại thời điểm đông nhất phải có đủ phòng, và quét tham lam đạt đúng số đó."}, {"q": "Giảm độ trễ lớn nhất: làm việc nào trước?", "o": ["Ngắn nhất", "Dài nhất", "Hạn chót sớm nhất", "Theo thứ tự đầu vào"], "a": 2, "e": "Earliest deadline first."}]);

